package com.mfg.eam.entity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="eam_equipment",catalog="src_eam") @Getter @Setter @NoArgsConstructor public class Equipment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="equipment_code")private String equipmentCode;@Column(name="equipment_name")private String equipmentName;@Column(name="equipment_model")private String equipmentModel;@Column(name="equipment_type")private String equipmentType;@Column(name="workshop_code")private String workshopCode;@Column(name="work_center")private String workCenter;@Column(name="location_desc")private String locationDesc;@Column(name="capacity_per_hour")private BigDecimal capacityPerHour;@Column(name="equipment_status")private String status="IDLE";@Column(name="health_score")private BigDecimal healthScore;@Column(name="health_level")private String healthLevel;
@Column(name="purchase_date")private LocalDate purchaseDate;@Column(name="purchase_price")private BigDecimal purchasePrice;
@Column(name="warranty_end_date")private LocalDate warrantyEndDate;
@Column(name="maintenance_cycle_days")private Integer maintenanceCycleDays;@Column(name="last_maintenance_date")private LocalDate lastMaintenanceDate;
@Column(name="created_at")private LocalDateTime createdAt;@Column(name="updated_at")private LocalDateTime updatedAt;}
